"""Coalesce half-open integer intervals."""


def coalesce(intervals):
    """Validate and merge nonempty integer intervals without changing the input.

    Pairs must be lists or tuples of two integers (excluding booleans),
    ordered from start to end. Invalid input raises ValueError.
    """
    try:
        iterator = iter(intervals)
    except TypeError as exc:
        raise ValueError("intervals must be iterable") from exc

    validated = []
    for pair in iterator:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise ValueError("each interval must be a list or tuple of length two")
        start, end = pair
        if (not isinstance(start, int) or isinstance(start, bool)
                or not isinstance(end, int) or isinstance(end, bool)):
            raise ValueError("interval endpoints must be integers, not booleans")
        if start > end:
            raise ValueError("interval start must not exceed its end")
        if start != end:
            validated.append((start, end))

    validated.sort()
    result = []
    for start, end in validated:
        if result and start <= result[-1][1]:
            result[-1] = (result[-1][0], max(result[-1][1], end))
        else:
            result.append((start, end))
    return result

